#include <vector>
#include <algorithm>

std::vector<std::pair<int, int>> free_slots(int limit, std::vector<std::pair<int, int>> busy) {
    if (limit <= 0) return {};

    std::vector<std::pair<int, int>> free_slots;
    for (const auto& interval : busy) {
        if (interval.first > interval.second) continue; // Skip reversed intervals
        if (free_slots.empty() || free_slots.back().second < interval.first) {
            free_slots.push_back(interval);
        } else {
            free_slots.back().second = std::max(free_slots.back().second, interval.second);
        }
    }

    return free_slots;
}
