#include <vector>
#include <algorithm>

int shortest_span(const std::vector<int>& values, long long threshold) {
    int min_length = INT_MAX;
    int start = 0;
    long long current_sum = 0;

    for (int end = 0; end < values.size(); ++end) {
        current_sum += values[end];

        while (current_sum > threshold) {
            current_sum -= values[start];
            ++start;
        }

        if (current_sum >= threshold) {
            min_length = std::min(min_length, end - start + 1);
        }
    }

    return min_length == INT_MAX ? 0 : min_length;
}
