#include <vector>
#include <unordered_map>
#include <queue>
#include <optional>

std::vector<std::vector<int>> build_layers(int n, const std::vector<std::pair<int,int>>& prerequisites) {
    std::unordered_map<int, std::vector<int>> graph;
    std::unordered_map<int, int> in_degree;
    std::queue<int> q;
    std::vector<std::vector<int>> result;

    // Initialize graph and in_degree
    for (int i = 0; i < n; ++i) {
        graph[i] = {};
        in_degree[i] = 0;
    }

    // Build graph and in_degree
    for (const auto& p : prerequisites) {
        graph[p.first].push_back(p.second);
        in_degree[p.second]++;
    }

    // Find all sources (tasks with no prerequisites)
    for (int i = 0; i < n; ++i) {
        if (in_degree[i] == 0) {
            q.push(i);
        }
    }

    // Perform topological sort
    while (!q.empty()) {
        int current = q.front();
        q.pop();
        result.push_back({current});

        for (int next : graph[current]) {
            in_degree[next]--;
            if (in_degree[next] == 0) {
                q.push(next);
            }
        }
    }

    // Check for cycles
    if (result.size() != n) {
        return {};
    }

    return result;
}
