#include <vector>
#include <string>
#include <map>
#include <algorithm>

std::vector<std::string> top_words(const std::vector<std::string>& words, int k) {
    if (k <= 0 || words.empty()) return {};

    std::map<std::string, int> word_count;
    for (const auto& word : words) {
        word_count[word]++;
    }

    std::vector<std::pair<std::string, int>> sorted_words(word_count.begin(), word_count.end());
    std::partial_sort(sorted_words.begin(), sorted_words.begin() + k, sorted_words.end(),
                      [](const std::pair<std::string, int>& a, const std::pair<std::string, int>& b) {
                          return a.second == b.second ? a.first < b.first : a.second > b.second;
                      });

    std::vector<std::string> result;
    for (int i = 0; i < k && i < sorted_words.size(); ++i) {
        result.push_back(sorted_words[i].first);
    }

    return result;
}
