#include <iostream>
#include <map>
#include <string>
#include <cassert>

int main() {
    std::map<std::string, int> inventory;

    for (;;) {
        std::string command;
        std::cin >> command;

        if (command == "PUT") {
            std::string name;
            int quantity;
            std::cin >> name >> quantity;
            inventory[name] += quantity;
        } else if (command == "TAKE") {
            std::string name;
            int quantity;
            std::cin >> name >> quantity;
            if (inventory[name] >= quantity) {
                inventory[name] -= quantity;
            } else {
                std::cout << "ERROR: Insufficient quantity of " << name << std::endl;
            }
        } else if (command == "QUERY") {
            std::string name;
            std::cin >> name;
            if (inventory.count(name)) {
                std::cout << inventory[name] << std::endl;
            } else {
                std::cout << "ERROR: Item not found" << std::endl;
            }
        } else if (command == "EOF") {
            break;
        } else {
            std::cout << "ERROR: Invalid command" << std::endl;
        }
    }

    return 0;
}
